 for(U base:{T,TT})for(U i=0;i<4;++i){U at=base+i*32;put(at,4,(seed+i)%8);put(at+4,4,(seed+i)%6);put(at+8,4,(seed+i)%13);put(at+12,4,(seed+i)%6==2?(seed%2?13u:0xffffffffu):i%2);put(at+16,4,(seed+i)%64);put(at+20,4,(seed+i)%32);}
