 Q trace=1469598103934665603ull;U entries=0,operations=0,calls=0;bool fired=false;auto emit=[&](U kind,U at,U w,U v){++entries;for(U x:{kind,at,w,v})for(U i=0;i<4;++i)trace=(trace^((x>>(i*8))&255))*1099511628211ull;};auto stop=[&](){if(fault&&++operations==fault)throw std::runtime_error("operation fixture");};
 dfre::MissionEventResourceBindings b;b.read=[&](U at,unsigned w){U v=get(at,w);emit('R',at,w,v);stop();return v;};b.write=[&](U at,unsigned w,U v){put(at,w,v);emit('W',at,w,v);if(!fired&&at==E+20&&w==1){fired=true;if(mutation&32){put(0x4f2bc8,4,3);put(0x4f2bcc,4,EE);put(E+8,4,AA);put(E+22,1,3);}}stop();};dfre::MissionEventMemory memory(b);Host host;host.memory=&memory;host.effect=[&](U site,const std::vector<U>& args){emit('C',site,U(args.size()),0);for(U v:args)emit('A',0,0,v);stop();if(++calls==1){if(mutation&1){put(E+4,4,TT);put(E+8,4,AA);}if(mutation&2){put(0x4f2bcc,4,EE);put(0x4f2bc8,4,1);put(0x4f2be4,4,5);}if(mutation&4){put(E+12,2,128);put(E+18,2,128);}if(mutation&8){put(E+21,1,0);put(E+22,1,1);}if(mutation&16)put(A+32+4,4,15);if(mutation&64)put(0x4f2bc8,4,seed%2?16:0);if(mutation&128){put(0x67f520,4,0);put(0x67f549,1,2);}}return seed%3?0x101u:0u;};dfre::EventStage stage(&host);stage.attach_source(memory);bool failed=false;U result=0;try{switch(op){case 0:stage.process_event_record(seed%37?E:0);break;case 1:result=stage.evaluate_event_triggers_record(E);break;case 2:result=stage.evaluate_trigger_record(T);break;case 3:stage.dispatch_action_record(A);break;case 4:stage.tick();break;case 5:stage.run_bit1_events();break;case 6:stage.run_bit2_events();break;default:stage.frame_driver_step();break;}}catch(const std::exception&){failed=true;}
